rev('AUTH26-017','A giới hạn B mua máy tối đa 500 triệu. B ký 550 triệu, bên bán không biết giới hạn; sau đọc đủ hợp đồng A đồng ý rõ phần vượt. Hợp đồng đã công chứng, ghi đúng giá 550 triệu; A nay muốn giảm thành 500 bằng sửa lỗi kỹ thuật, bên bán không đồng ý. Kết luận đúng?',
'A bị ràng buộc phần đã đồng ý; giảm giá cần sửa nội dung với bên bán, không phải lỗi kỹ thuật.',[
('A đồng ý chỉ chữa tư cách B, không chữa giá; công chứng viên được sửa giá về giới hạn ban đầu.','Chấp thuận phần vượt ràng buộc giá; thay giá ảnh hưởng quyền nghĩa vụ.'),('Giá 550 triệu ràng buộc A, nhưng hạn mức gốc là căn cứ sửa kỹ thuật không cần bên bán ký.','Không biến thay đổi giá đã thỏa thuận đúng thành lỗi kỹ thuật.'),('B ký vượt nên giá 550 triệu mất hiệu lực; hai bên chỉ cần thông báo giá 500 cho tổ chức công chứng.','Bỏ ngoại lệ chủ chấp thuận và thủ tục sửa nội dung.')],
'DS143 cho phần vượt ràng buộc khi A đồng ý. Giá 550 triệu phản ánh đúng thỏa thuận, nên giảm giá thay quyền nghĩa vụ. CC52 không áp dụng; CC53 cần ý chí các bên theo hình thức và thủ tục sửa nội dung.','DS:143 CC:52 CC:53',['Áp chấp thuận phần vượt','Phân biệt lỗi sao chép với thay giá','Kiểm tra đồng ý sửa nội dung'])
rev('COMP26-DD-007','Văn phòng X định thay bảo hiểm nghề nghiệp bằng cam kết CCV tự bồi thường. Một hợp đồng đã được Tòa án tuyên vô hiệu; bên mua yêu cầu người bán hoàn tiền, đồng thời yêu cầu X bồi thường thiệt hại do lỗi công chứng đã chứng minh. Cần phân biệt các nghĩa vụ thế nào?',
'Vẫn mua bảo hiểm; tách hoàn trả của các bên khỏi bồi thường do lỗi công chứng của X.',[
('X mua bảo hiểm thì người bán được giữ tiền; nghĩa vụ hoàn trả chuyển sang tổ chức bảo hiểm.','Bảo hiểm nghề nghiệp không thay hậu quả hoàn trả giữa các bên giao dịch vô hiệu.'),('Người bán hoàn tiền là đủ để thay bảo hiểm và loại khoản thiệt hại do lỗi X.','Hoàn trả không tự loại nghĩa vụ bảo hiểm hoặc bồi thường thiệt hại độc lập.'),('CCV ký cam kết thì X được miễn mua bảo hiểm; bên mua phải chọn hoặc hoàn trả hoặc bồi thường.','Cam kết không thay bảo hiểm; hai căn cứ nghĩa vụ không tự loại nhau.')],
'Bảo hiểm nghề nghiệp là nghĩa vụ tổ chức, không thay bằng cam kết. DS131 xử lý hoàn trả và thiệt hại giao dịch vô hiệu; CC40 xử lý thiệt hại do lỗi công chứng. Không cộng trùng cùng thiệt hại, nhưng cũng không tự loại nghĩa vụ độc lập.','DS:131 CC:40',['Giữ nghĩa vụ mua bảo hiểm','Tách hoàn trả giao dịch vô hiệu','Xác định thiệt hại do lỗi công chứng'])
rev('COMP26-DS-002','A–W cùng đồng ý bằng văn bản thế chấp máy chung trị giá 400 triệu bảo đảm gốc 500 triệu, lãi 20 triệu; mô tả theo nhóm nhưng xác định chính xác máy. Không thỏa thuận khác về phạm vi, không áp trường hợp một tài sản bảo đảm nhiều nghĩa vụ. Nhận định đúng?',
'Không loại vì mô tả xác định được hoặc giá trị thấp; phạm vi mặc định gồm gốc và lãi 520 triệu.',[
('Mô tả xác định được và hai chủ đồng ý nên phạm vi nghĩa vụ tự giảm bằng giá máy 400 triệu.','Giá tài sản không tự giảm nghĩa vụ được bảo đảm.'),('Giá 400 triệu không cấm thế chấp, nhưng mô tả theo nhóm phải đổi dù vẫn nhận diện chính xác máy.','DS295 cho mô tả chung có thể xác định tài sản.'),('Mô tả nhóm được chấp nhận; riêng phần lãi cần thêm một hợp đồng thế chấp mới vì thấp giá trị tài sản.','Phạm vi mặc định đã gồm lãi nếu không thỏa thuận khác, không suy từ giá tài sản.')],
'DS295 cho mô tả chung nhưng phải xác định được và không bắt giá trị bảo đảm luôn lớn hơn nghĩa vụ trong tình huống này. DS293 xác định phạm vi mặc định gồm lãi. HN35 kiểm tra thỏa thuận chủ chung đã đáp ứng.','DS:295 DS:293 HN:35',['Kiểm tra nhận diện tài sản','Tách giá trị máy khỏi phạm vi nghĩa vụ','Kiểm tra thỏa thuận chủ chung'])
rev('COMP26-QT-004','X sửa lỗi đánh máy địa chỉ không đổi quyền, đã thu hồi nhưng không thể lấy đủ bản gốc. Cùng hồ sơ, A–B muốn giảm lợi ích C trong hợp đồng đã công chứng; C đã đồng ý hưởng, nay chưa đồng ý giảm. Cách xử lý đúng?',
'Sửa các bản gốc thu hồi được và thông báo; giảm lợi ích C cần sửa nội dung và đồng ý C.',[
('Thu hồi thiếu một bản thì dừng sửa mọi bản; A–B cùng ký đủ để giảm lợi ích C chưa thực hiện.','Luật có ngoại lệ không thể thu hồi đủ; C đã đồng ý hưởng được bảo vệ dù chưa thực hiện.'),('Sửa bản lưu và thông báo là đủ cho cả địa chỉ và lợi ích C nếu A–B cùng đồng ý bằng văn bản.','Đổi lợi ích là nội dung; ý chí hai bên gốc chưa thay được đồng ý C.'),('Sửa địa chỉ được nhưng không phải thông báo; phần lợi ích chỉ cần bổ sung nhân chứng độc lập.','Vẫn cần thông báo; nhân chứng không thay đồng ý người thứ ba.')],
'CC52 cho sửa những bản thu hồi được trong ngoại lệ và vẫn thông báo. CC53 xử lý sửa nội dung; DS417 đòi C đồng ý khi đã chấp nhận hưởng, dù hợp đồng chưa thực hiện.','CC:52 CC:53 DS:417',['Tách lỗi kỹ thuật và đổi quyền','Áp ngoại lệ thu hồi nhưng giữ thông báo','Giữ điều kiện người thứ ba đã đồng ý hưởng'])
rev('COMP26-TS-008','CCV K không hành nghề 12 tháng do quyết định tạm đình chỉ. Hết đình chỉ, lý do dẫn đến đình chỉ vẫn còn. K muốn dùng ngoại lệ nghỉ do đình chỉ để tiếp tục ký ngay và ký thay người lập di chúc bằng giấy ủy quyền. Phương án đúng?',
'Không miễn nhiệm máy móc vì nghỉ 12 tháng; xét căn cứ còn lý do đình chỉ, và không cho lập di chúc thay.',[
('Ngoại lệ nghỉ 12 tháng cho K ký ngay; giấy ủy quyền đủ rộng thì K được lập di chúc thay.','Ngoại lệ một căn cứ không miễn mọi căn cứ khác và không cho đại diện lập di chúc.'),('Phải miễn nhiệm vì đủ 12 tháng, nhưng trước quyết định mới K được ký di chúc nhân danh khách.','Bỏ ngoại lệ nghỉ do đình chỉ và yêu cầu cá nhân tự lập di chúc.'),('Chờ tổ chức xác nhận K khỏe rồi bỏ căn cứ đình chỉ; chỉ cần khách điểm chỉ vào di chúc K đã quyết định.','Xác nhận sức khỏe không thay xử lý lý do đình chỉ; ý chí di chúc phải của người lập.')],
'Điều 16 phân biệt nghỉ do đình chỉ với căn cứ riêng hết đình chỉ mà lý do còn. Không từ ngoại lệ thứ nhất suy quyền hành nghề ngay. DS630 và CC58 giữ ý chí, yêu cầu trực tiếp người lập di chúc, không cấp quyền lập thay.','CC:58 DS:630',['Phân biệt hai căn cứ miễn nhiệm','Kiểm tra lý do đình chỉ còn hay hết','Giữ điều kiện lập di chúc trực tiếp'])
rev('FAM26-018','H–W có nợ hợp lệ với C trước khi sửa chế độ tài sản. Họ công chứng sửa để W nhận trả hết nợ, C không đồng ý miễn H. H còn ủy quyền K thông báo rằng H đã hết nợ. Nhận định đúng?',
'Nợ có trước với C được giữ; thỏa thuận H–W và thông báo K không tự miễn H.',[
('Văn bản sửa đã công chứng nên H hết nợ sau khi K giao thông báo, không cần C chấp thuận.','Công chứng và thông báo không tự thay quyền chủ nợ có trước.'),('C phải dự buổi sửa thì nợ cũ mới tiếp tục; vắng mặt được xem là đồng ý chuyển hết sang W.','Không có cơ chế suy vắng mặt thành miễn nghĩa vụ.'),('Nợ cũ còn nhưng K được tự thỏa thuận miễn H vì có quyền thông báo thay H.','Quyền thông báo không bao gồm quyền định đoạt nghĩa vụ của C.')],
'HN49 giữ quyền, nghĩa vụ tài sản có trước sửa chế độ, trừ thỏa thuận liên quan khác. DS141 giới hạn K vào thông báo; giấy đại diện của H không cấp quyền quyết định thay C.','HN:49 DS:141',['Xác định nghĩa vụ có trước','Kiểm tra C có đồng ý thay đổi không','Giới hạn quyền thông báo của K'])
rev('IMP-SEP24-014','H thuê đất Nhà nước trả tiền một lần cả thời gian thuê, quyền đất và nhà hợp pháp là tài sản chung H–W trị giá ròng 6 tỷ; đủ điều kiện để thừa kế, không có thỏa thuận tỷ lệ khác. H chết, chỉ W và con B trưởng thành có khả năng lao động là hàng thứ nhất. Di chúc cho X toàn phần H. W được tổng giá trị tối thiểu bao nhiêu?',
'4 tỷ: 3 tỷ sở hữu và 1 tỷ thừa kế bắt buộc.',[
('5 tỷ: W sở hữu 3 tỷ và nhận hai phần ba toàn di sản H vì là vợ.','Mức bắt buộc tính trên một suất pháp luật, không toàn di sản.'),('3 tỷ: W chỉ nhận phần sở hữu, quyền đất thuê không thuộc phần H để thừa kế.','Dữ kiện trả một lần và đủ điều kiện cho thừa kế quyền đất, khác thuê năm.'),('2 tỷ: toàn 6 tỷ được tính là di sản H rồi chia mức bắt buộc cho W.','Chưa tách quyền sở hữu W ra khỏi di sản.')],
'Quyền đất thuê trả một lần được xét thừa kế theo chế độ quyền tương ứng. HN66 tách W 3 tỷ, H 3 tỷ. Suất giả định 1,5 tỷ theo DS651; DS644 bảo vệ W 1 tỷ, tổng 4 tỷ.','HN:66 DS:651 DS:644',['Phân biệt chế độ quyền thuê đất','Tách quyền sở hữu khỏi di sản','Tính bắt buộc trên suất giả định'])
rev('IMP-T60-011','A giao B 100 lít nhiên liệu để dùng sản xuất, thỏa thuận sáu tháng sau trả 100 lít cùng loại, chất lượng. A–B gọi là thuê và định nhận lại đúng nhiên liệu ban đầu; không có thỏa thuận mua bán. Cách phân loại phù hợp?',
'Không thể thuê để hoàn chính vật tiêu hao đã dùng; xét cơ chế vay và hoàn vật cùng loại.',[
('Giữ cơ chế thuê vì đã ghi hạn sáu tháng; B trả nhiên liệu cùng loại được xem là hoàn chính vật ban đầu.','Tên và thời hạn không đổi tính chất tiêu hao và nghĩa vụ hoàn vật cùng loại.'),('Đổi thành mua bán vì nhiên liệu được dùng; lời hứa trả vật cùng loại chỉ là nghĩa vụ phụ.','Phải xét cơ chế vay theo thỏa thuận hoàn vật cùng loại, không tự đổi thành mua bán.'),('Giữ thuê nếu A không chuyển quyền sở hữu trên giấy; tính chất vật tiêu hao được đánh giá khi B trả.','Vật mất tính chất sau sử dụng nên không làm đối tượng thuê theo quy tắc này.')],
'Phải phân biệt trả chính tài sản thuê với trả lượng vật cùng loại của giao dịch vay. Tính tiêu hao của nhiên liệu không đổi do tên hợp đồng; cần chọn cơ chế phù hợp với nội dung và điều kiện hiệu lực, không tự biến thành mua bán.','DS:463 DS:464',['Xác định vật mất sau sử dụng','Đọc nội dung hoàn vật cùng loại','Không quyết định loại giao dịch bằng tên gọi'])
rev('IMP-T60-027','H–W có tiền chung 2,4 tỷ, không nợ. H lập di chúc miệng trong nguy hiểm tính mạng, đủ thủ tục ban đầu, cho X toàn phần H. Ba tháng sau H còn sống minh mẫn; tháng thứ tư H chết, chỉ W và con B có quyền hàng thứ nhất, không di chúc khác. Chia thế nào?',
'W tổng 1,8 tỷ; B 600 triệu; di chúc miệng đã mặc nhiên bị hủy bỏ.',[
('W tổng 1,6 tỷ; X 800 triệu; B không hưởng vì di chúc miệng đủ thủ tục ban đầu.','Bỏ sự kiện sống minh mẫn sau ba tháng và chuyển chia pháp luật.'),('W và B mỗi người 1,2 tỷ vì di chúc bị hủy nên cả tiền chung được chia thừa kế.','Phải tách phần sở hữu W trước khi chia phần H.'),('W sở hữu 1,2 tỷ; X nhận 1,2 tỷ còn lại vì H chỉ sống thêm một tháng sau mốc ba tháng.','Sau ba tháng còn sống minh mẫn, di chúc miệng đã bị hủy theo luật.')],
'DS629 hủy di chúc miệng khi sau ba tháng còn sống minh mẫn. HN66 tách W 1,2 tỷ; phần H 1,2 tỷ chia pháp luật W,B mỗi 600 triệu theo DS650,651. W tổng 1,8 tỷ.','DS:629 HN:66 DS:650 DS:651',['Kiểm tra hiệu lực sau hồi phục','Tách quyền sở hữu W','Chia phần H theo pháp luật'])
rev('IMP-T60-052','H–W dùng thu nhập hôn nhân để nhận giao đất có thu tiền sử dụng đất; không có ngoại lệ khác. H giao K quyền nộp hồ sơ và thanh toán khoản tiền này, không cho ký chuyển nhượng. K gọi khoản tiền là tiền thuê đất rồi muốn ký bán nhân danh H. Nhận định đúng?',
'Phân loại tiền sử dụng đất; xét quyền đất chung; quyền nộp, trả tiền chưa đủ cho K ký bán.',[
('Đổi tên tiền thành tiền thuê không ảnh hưởng quyền K: đã thanh toán thì K có quyền bán thay cả H–W.','Thanh toán và tên khoản tiền không tự cấp quyền định đoạt hoặc quyền W.'),('Đúng tiền sử dụng đất nên H là chủ riêng; K có thể ký bán khi xuất trình biên lai nộp.','Nguồn chung và phạm vi đại diện phải xét độc lập với tên khoản tiền.'),('Quyền đất là chung nhưng K được suy quyền bán từ việc hoàn tất nghĩa vụ tài chính của hồ sơ.','Nộp và thanh toán khác ký hợp đồng chuyển quyền.')],
'Giao đất có thu tiền thuộc nhóm tiền sử dụng đất, khác thuê. HN33 xét quyền đất từ nguồn chung; DS141 giới hạn K vào công việc đã cấp. HN35 còn yêu cầu ý chí định đoạt bất động sản chung, không suy từ biên lai.','HN:33 DS:141 HN:35',['Phân loại nghĩa vụ tài chính','Xác định nguồn hình thành quyền đất','Tách quyền nộp hồ sơ khỏi quyền bán'])
rev('INH26-012','Nhà di sản đang thế chấp, khoản vay còn tồn tại. B,C chỉ cử Long quản lý, không chuyển quyền. Sau đó Long muốn bán nhà với đồng ý bằng văn bản B, nhưng C và bên nhận thế chấp chưa đồng ý; nhà không phải hàng hóa luân chuyển. Cần phân biệt gì?',
'Có thể xét cử quản lý; việc bán còn cần đồng ý các người hưởng và bên nhận thế chấp theo luật.',[
('B đồng ý bằng văn bản đủ cho Long bán; bên nhận thế chấp chỉ được thông báo như trường hợp cho thuê.','Bán tài sản thế chấp loại này khác thuê; còn thiếu C.'),('Cử quản lý tự chuyển nhà sang Long, nên Long tự bán nếu dùng tiền trả khoản vay.','Quản lý không phải sở hữu hoặc quyền định đoạt độc lập.'),('Có thế chấp thì phải giải chấp mới cử quản lý; sau đó B đồng ý đủ để Long bán cả nhà.','Không đồng nhất cử quản lý với định đoạt và bỏ quyền C.')],
'DS616,617 phân biệt cử quản lý và bán cần đồng ý bằng văn bản người thừa kế. DS321 giữ điều kiện định đoạt tài sản thế chấp. CC42 kiểm tra quyền, không dùng việc chọn đúng người quản lý thay điều kiện bán.','DS:616 DS:617 DS:321 CC:42',['Phân biệt quản lý với định đoạt','Kiểm tra ý chí các người hưởng','Kiểm tra điều kiện tài sản thế chấp'])
rev('INH26-028','H–W có nhà chung 3 tỷ, không nợ. H chết không di chúc; cha mẹ đã chết, có con ruột B và con riêng W là C. H–C đã được chứng minh chăm sóc, nuôi dưỡng như cha con, chưa nhận con nuôi. Không có người khác hoặc căn cứ loại quyền. W nhận tổng bao nhiêu?',
'2 tỷ: 1,5 tỷ sở hữu và 500 triệu thừa kế.',[
('2,25 tỷ: 1,5 tỷ sở hữu và 750 triệu, vì C chưa được đăng ký nhận nuôi.','Bỏ quan hệ nuôi dưỡng như cha con được DS654 bảo vệ.'),('1 tỷ: chia toàn nhà cho W,B,C như ba người cùng hàng.','Không đưa phần sở hữu riêng của W trong khối chung vào di sản H.'),('3 tỷ: W quản lý nhà, còn B,C chỉ có quyền xin phần khi W đồng ý.','Quản lý không tạo sở hữu toàn bộ hoặc quyền quyết định phần hưởng của các con.')],
'HN66 tách W 1,5 tỷ, di sản H 1,5 tỷ. DS654 cho C quyền theo quan hệ nuôi dưỡng như cha con, không đòi đăng ký con nuôi để thay điều kiện này. Ba người chia đều 500 triệu, W tổng 2 tỷ.','HN:66 DS:654 DS:651',['Tách phần sở hữu W','Xét quyền con riêng theo nuôi dưỡng','Chia suất cùng hàng'])
rev('REFIN26-CC-008','Văn phòng X thiếu nguồn thu nên xin ngân sách cấp chi thường xuyên. X đã bồi thường thiệt hại do lỗi K công chứng, K đã nghỉ; X muốn thu thêm khoản không có căn cứ từ khách để bù. Phương án đúng?',
'Tự chủ bằng nguồn thu hợp pháp; xét hoàn trả theo lỗi từ K, không tự đặt khoản thu từ khách.',[
('Nguồn thu thiếu cho phép X tạm dùng khoản thu khách tự đặt; K nghỉ thì không còn nghĩa vụ hoàn trả.','Không hợp pháp hóa khoản thu và không xóa hoàn trả do đã nghỉ.'),('Ngân sách phải bù vì công chứng là dịch vụ công; hoàn trả K chỉ đặt ra khi X còn đủ doanh thu.','Tự chủ không mặc nhiên được bao cấp; hoàn trả không phụ thuộc doanh thu như nêu.'),('X đòi khách bồi hoàn rồi miễn K vì K không còn ký hồ sơ; khoản đó được coi là nguồn thu hợp pháp.','Không có căn cứ chuyển trách nhiệm người gây lỗi sang khách.')],
'Nguyên tắc tài chính là tự chủ bằng nguồn thu hợp pháp. CC40 có cơ chế hoàn trả theo lỗi kể cả người gây lỗi đã nghỉ; không tự tạo khoản thu hoặc quyền yêu cầu ngân sách bù thiếu.','CC:40 CC:9',['Xác định nguồn thu hợp pháp','Tách bồi thường khách và hoàn trả nội bộ','Không tự đặt khoản thu để bù thiếu'])
rev('REFIN26-CC-018','CCV K rút vốn Văn phòng, đã được chấp thuận và số thành viên còn lại đủ; thông báo mới một tháng, đang giữa năm, báo cáo năm chưa thông qua. Phần vốn là tài sản chung K–W tạo thu nhập chủ yếu, W chưa đồng ý bằng văn bản. K cần hoàn tất gì?',
'Đủ mốc thông báo, cuối năm và báo cáo; đồng thời xét văn bản đồng ý định đoạt tài sản chung.',[
('Đủ thành viên và phiếu chấp thuận cho rút ngay; văn bản W chỉ cần khi vốn là quyền sử dụng đất.','Còn mốc thủ tục và điều kiện tài sản tạo thu nhập chủ yếu.'),('Kéo thông báo thành sáu tháng thì được rút giữa năm; W đồng ý miệng đủ vì vốn không phải nhà.','Còn mốc cuối năm, báo cáo và hình thức thỏa thuận với tài sản thuộc trường hợp này.'),('W ký văn bản thì được bỏ mốc thủ tục; quyền rút vốn phụ thuộc ý chí vợ chồng thay nội bộ Văn phòng.','Thỏa thuận gia đình không thay điều kiện nghề nghiệp và thủ tục rút vốn.')],
'Rút vốn phải đủ thời gian thông báo sáu tháng, mốc cuối năm và báo cáo được thông qua theo điều kiện luật. HN35 còn yêu cầu văn bản khi định đoạt tài sản chung tạo thu nhập chủ yếu; đủ điều kiện nội bộ không thay quyền W.','HN:35 HN:33',['Kiểm tra mốc và thủ tục rút vốn','Xác định phần vốn chung','Giữ điều kiện định đoạt tạo thu nhập chủ yếu'])
rev('REFIN26-CC-032','Văn phòng tạm ngừng hợp lệ do bất khả kháng kéo dài trên 12 tháng, sự kiện vẫn còn. Một hồ sơ khách đã tiếp nhận hợp lệ bị trở ngại khách quan, các bên muốn tự coi mọi thời hạn đã được kéo dài mà không ghi nhận bằng văn bản. Phương án đúng?',
'Xét ngoại lệ tạm ngừng do bất khả kháng; kéo dài thời hạn hồ sơ cần thỏa thuận bằng văn bản đúng điều kiện.',[
('Bất khả kháng giữ ngoại lệ tạm ngừng nhưng mọi hồ sơ trong Văn phòng đều tự được kéo dài không cần ghi nhận.','Ngoại lệ tạm ngừng không thay điều kiện thời hạn riêng hồ sơ.'),('Quá 12 tháng phải thu hồi bất kể lý do; thỏa thuận miệng của khách đủ giữ thời hạn hồ sơ.','Bỏ ngoại lệ tạm ngừng và hình thức thỏa thuận kéo dài.'),('Khách ký văn bản kéo dài hồ sơ thì được coi như phê duyệt Văn phòng tạm ngừng không giới hạn lý do.','Thỏa thuận hồ sơ không quyết định chế độ tạm ngừng tổ chức.')],
'Phải phân biệt thời gian tạm ngừng tổ chức theo bất khả kháng với thời hạn giải quyết từng hồ sơ. CC45 có cơ chế kéo dài khi đúng căn cứ và thỏa thuận bằng văn bản, không tự suy từ việc tạm ngừng.','CC:45 CC:42',['Kiểm tra ngoại lệ tạm ngừng','Xác định trở ngại hồ sơ cụ thể','Hoàn thiện thỏa thuận kéo dài riêng'])
rev('REFIN26-QT-021','K chỉ quét hợp đồng giấy thành PDF, không thực hiện chuyển đổi đủ điều kiện. K muốn dùng PDF để ký giao dịch mới nhân danh A; quyền K đã hết hạn trước ngày ký mới, A không chấp thuận và không có ngoại lệ ràng buộc. Phương án đúng?',
'PDF quét chưa tự bằng bản gốc điện tử; cũng không khôi phục quyền K đã hết để ký giao dịch mới.',[
('K gửi đủ ảnh dấu thì PDF được coi bản gốc; nhưng cần ghi thêm ngày ủy quyền trên ảnh để tiếp tục ký.','Ảnh dấu không đủ chuyển đổi và ghi ngày không gia hạn đại diện.'),('A từng cấp quyền nên K được ký mới; PDF chỉ cần bản in để giải quyết thiếu chữ ký số.','Quyền đã hết không tự tiếp tục; bản in không thay điều kiện chuyển đổi.'),('Làm lại chuyển đổi đủ điều kiện sẽ đồng thời gia hạn quyền K đến lúc tổ chức ký số.','Hiệu lực bản chuyển đổi không tạo thời hạn đại diện mới.')],
'CC64 đòi điều kiện chuyển đổi, không đồng nhất PDF quét với bản gốc điện tử. DS140,141 xác định quyền K đã hết và phạm vi; sửa dạng tài liệu không khôi phục quyền ký giao dịch mới.','CC:64 DS:140 DS:141',['Xét điều kiện chuyển đổi','Chốt quyền đại diện tại ký mới','Không dùng dạng tài liệu để tạo quyền'])
rev('SRC26-010','Hồ sơ bán nhà chỉ tên H nhưng nhà mua bằng thu nhập hôn nhân; W chưa ký hoặc ủy quyền. H đề nghị lời chứng chỉ xác nhận chữ ký, vì dự thảo do luật sư soạn và H đã tự chịu trách nhiệm. Xử lý đúng?',
'Không thu hẹp lời chứng; làm rõ nhà chung và ý chí định đoạt W trước khi chứng nhận.',[
('Giữ lời chứng đủ nội dung nhưng coi tên H trên giấy là đủ quyền bán, khỏi xét W.','Nội dung lời chứng không thay việc kiểm tra quyền thực tế.'),('W ký thêm nhân chứng thì được dùng lời chứng chỉ xác nhận chữ ký H, không xét nội dung hợp đồng.','Nhân chứng không thay quyền W hoặc nội dung lời chứng giao dịch.'),('Luật sư đã soạn thì chỉ cần chứng nhận chữ ký; nguồn tiền hôn nhân được giải quyết sau đăng ký chuyển quyền.','Không bỏ kiểm tra tính hợp pháp, quyền và tự nguyện trước công chứng.')],
'Lời chứng giao dịch phải thể hiện các nội dung luật định về tự nguyện, năng lực, mục đích và nội dung hợp pháp. HN33,35 đòi xác định tài sản chung, thỏa thuận định đoạt bằng văn bản; người soạn dự thảo không thay nghĩa vụ kiểm tra.','HN:33 HN:35 CC:42',['Kiểm tra nội dung lời chứng','Xác định nhà chung từ nguồn tiền','Kiểm tra quyền và ý chí W'])
rev('VER26-049','H–W cùng có quyền đất; hợp đồng cho thuê thuộc nhóm công chứng, chứng thực theo yêu cầu, không có quy định chuyên ngành khác bắt buộc. H chỉ ủy quyền K nộp hồ sơ, chưa cho ký; W chưa đồng ý giao dịch. Các bên tự nguyện yêu cầu công chứng thuê. Cần xử lý thế nào?',
'Có thể xét yêu cầu tự nguyện; vẫn làm rõ đồng ý W và quyền ký K, không suy từ quyền nộp.',[
('Công chứng theo yêu cầu nên quyền nộp hồ sơ đủ cho K ký hợp đồng, W chỉ cần nhận thông báo.','Tự nguyện công chứng không miễn điều kiện đại diện và định đoạt chung.'),('Thuê không bắt buộc nên Văn phòng phải từ chối công chứng, dù sau đó đủ quyền và hồ sơ.','Không bắt buộc không có nghĩa bị cấm tự nguyện công chứng.'),('W đồng ý bằng văn bản thì K được ký nhờ hợp đồng thuê không bắt buộc, không cần sửa quyền gốc.','Đồng ý W không tự mở phạm vi đại diện K.')],
'Nhóm hợp đồng này được công chứng theo yêu cầu. Điều kiện hình thức khác quyền ký; HN35 và DS141 vẫn cần kiểm tra quyền chủ chung và phạm vi K. Nộp hồ sơ không đồng nghĩa ký giao dịch.','HN:35 DS:141 CC:42',['Phân biệt tự nguyện và bắt buộc','Kiểm tra quyền của chủ chung','Tách nộp hồ sơ khỏi ký thuê'])
